package edu.minibank.util;
import edu.minibank.model.annotation.*; import java.lang.reflect.*; import java.util.*;
public final class AnnotationValidator { private AnnotationValidator(){} public static String[] validate(Object obj){List<String> errors=new ArrayList<>();for(Class<?> type=obj.getClass();type!=null;type=type.getSuperclass())for(Field f:type.getDeclaredFields()){try{f.setAccessible(true);Object v=f.get(obj);if(f.isAnnotationPresent(Positive.class)&&v instanceof Number n&&n.longValue()<=0)errors.add(f.getName()+" "+f.getAnnotation(Positive.class).message());MaxLength m=f.getAnnotation(MaxLength.class);if(m!=null&&v instanceof String s&&s.length()>m.value())errors.add(f.getName()+" must be at most "+m.value()+" characters");}catch(ReflectiveOperationException e){errors.add("Could not validate "+f.getName()+": "+e.getMessage());}}return errors.toArray(String[]::new);} }
